    {
      userId: user.id,
      sessionId: session.id,
      kycVerified: Boolean(user.kycVerified),
      kybVerified: Boolean(user.kybVerified),
      type: user.type,
      role: user.role,
    },
    accessTokenExpiresAt
  );

  return {
    userId: user.id,
    accessToken,
    accessTokenExpiresAt,
    refreshToken,
    refreshTokenExpiresAt: new Date(now + authConfig.absoluteSessionTtlMs),
  };
}

